const output = [];

for (const item of $input.all()) {
  const query = item.json.query;
  const results = item.json.results || [];

  for (const result of results) {
    output.push({
      json: {
        source_query: query,
        url: result.url,
        title: result.title,
        content: result.content,
        score: result.score,
      },
    });
  }
}

return output;

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const url = item.json.url;

  if (!url || seen.has(url)) {
    continue;
  }

  seen.add(url);

  output.push({
    json: item.json,
  });
}

return output;

const events = $input.all();

return events.map(item => {
  const event = item.json;

  return {
    json: {
      name: event.name,
      date: event.startDate?.slice(0, 10) ?? null,
      time: event.time || event.startDate?.slice(11, 16) || null,
      price: event.price ?? null,

      venue: event.location?.venue ?? null,
      city: event.location?.city ?? null,
      address: event.location?.address ?? null,

      distanceKm: event.distanceKm ?? null,

      description: event.description ?? null,

      sourceUrls: event.sourceUrls ?? [],
    },
  };
});

const events = $input.all().map(item => item.json);

// Production: use Build Search Context.
// Test: fall back to the current fixture range.
let START_DATE = '2026-09-28';
let LOOKAHEAD_WEEKS = 3;

try {
  const context = $('Python — Build Search Context').first().json;

  if (context.start_date) {
    START_DATE = context.start_date;
  }

  if (context.config?.lookahead_weeks) {
    LOOKAHEAD_WEEKS =
      Number(context.config.lookahead_weeks);
  }
} catch {
  // Build Search Context was not executed.
  // Use the test values above.
}

function addDays(dateString, days) {
  const date = new Date(
    `${dateString}T00:00:00`
  );

  date.setDate(
    date.getDate() + days
  );

  return date.toISOString().slice(0, 10);
}

const weeks = [];

for (
  let i = 0;
  i < LOOKAHEAD_WEEKS;
  i++
) {
  const weekStart =
    addDays(
      START_DATE,
      i * 7
    );

  const weekEnd =
    addDays(
      weekStart,
      6
    );

  weeks.push({
    weekStart,
    weekEnd,
    events: [],
  });
}

for (const event of events) {
  if (!event.date) {
    continue;
  }

  const week =
    weeks.find(week =>
      event.date >= week.weekStart &&
      event.date <= week.weekEnd
    );

  if (week) {
    week.events.push(event);
  }
}

for (const week of weeks) {
  week.events.sort((a, b) => {
    return `${a.date} ${a.time ?? ''}`
      .localeCompare(
        `${b.date} ${b.time ?? ''}`
      );
  });
}

return weeks.map(week => ({
  json: week,
}));

const weeks = $input.all().map(item => item.json);

function formatDate(dateString) {
  const date = new Date(`${dateString}T00:00:00`);

  return new Intl.DateTimeFormat('fi-FI', {
    day: 'numeric',
    month: 'numeric',
  }).format(date);
}

function getWeekday(dateString) {
  const date = new Date(`${dateString}T00:00:00`);

  return new Intl.DateTimeFormat('fi-FI', {
    weekday: 'short',
  }).format(date);
}

function normalizeCity(city) {
  const cities = {
    Jyvaskyla: 'Jyväskylä',
    Jamsa: 'Jämsä',
    Aanekoski: 'Äänekoski',
    Maentyharju: 'Mäntyharju',
    Pieksamaki: 'Pieksämäki',
    Sysma: 'Sysmä',
  };

  return cities[city] ?? city;
}

let html = `
<!DOCTYPE html>
<html lang="fi">

<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Tapahtumat</title>
</head>

<body style="
  font-family: Arial, sans-serif;
  line-height: 1.4;
  margin: 0;
  padding: 14px;
  box-sizing: border-box;
">
`;

for (const week of weeks) {
  html += `
  <h2 style="
    margin-top: 24px;
    margin-bottom: 10px;
  ">
    ${formatDate(week.weekStart)}–${formatDate(week.weekEnd)}
  </h2>

  <table
    cellpadding="8"
    cellspacing="0"
    style="
      width: 100%;
      max-width: 100%;
      box-sizing: border-box;
      border-collapse: collapse;
      font-size: 14px;
      margin-bottom: 28px;
    "
  >
    <thead>
      <tr style="background-color: #f2f2f2;">

        <th style="
          text-align: left;
          border: 1px solid #ddd;
          white-space: nowrap;
        ">
          Viikonpäivä
        </th>

        <th style="
          text-align: left;
          border: 1px solid #ddd;
          white-space: nowrap;
        ">
          Päivä
        </th>

        <th style="
          text-align: left;
          border: 1px solid #ddd;
          white-space: nowrap;
        ">
          Aika
        </th>

        <th style="
          text-align: left;
          border: 1px solid #ddd;
        ">
          Tapahtuma
        </th>

        <th style="
          text-align: left;
          border: 1px solid #ddd;
        ">
          Kaupunki
        </th>

        <th style="
          text-align: left;
          border: 1px solid #ddd;
        ">
          Paikka
        </th>

      </tr>
    </thead>

    <tbody>
  `;

  for (const event of week.events) {
    const sourceUrl = event.sourceUrls?.[0];

    html += `
      <tr>

        <td style="
          border: 1px solid #ddd;
          white-space: nowrap;
        ">
          ${getWeekday(event.date)}
        </td>

        <td style="
          border: 1px solid #ddd;
          white-space: nowrap;
        ">
          ${formatDate(event.date)}
        </td>

        <td style="
          border: 1px solid #ddd;
          white-space: nowrap;
        ">
          ${event.time || '—'}
        </td>

        <td style="
          border: 1px solid #ddd;
        ">
          ${
            sourceUrl
              ? `<a href="${sourceUrl}">${event.name}</a>`
              : event.name
          }
        </td>

        <td style="
          border: 1px solid #ddd;
        ">
          ${normalizeCity(event.city) || '—'}
        </td>

        <td style="
          border: 1px solid #ddd;
        ">
          ${event.venue || '—'}
        </td>

      </tr>
    `;
  }

  html += `
    </tbody>
  </table>
  `;
}

html += `
</body>
</html>
`;

return [
  {
    json: {
      subject: 'Tapahtumat – seuraavat 3 viikkoa',
      html,
    },
  },
];

const blockedDomains = [
  'concerts50.com',
];

const blockedPathPatterns = [
  /\/events\/?$/i,
  /\/event\/?$/i,
  /\/concerts\/?$/i,
  /\/comedy\/?$/i,
  /\/stand-up\/?$/i,
  /\/festivals\/?$/i,
  /\/festivals?\/?$/i,
  /\/venues?\/?$/i,
  /\/clubs\/?$/i,
  /\/nightlife/i,
  /\/city-[^/]+$/i,
];

return $input.all().filter(item => {
  const url = String(item.json.url ?? '').toLowerCase();

  if (!url) {
    return false;
  }

  if (blockedDomains.some(domain => url.includes(domain))) {
    return false;
  }

  if (blockedPathPatterns.some(pattern => pattern.test(url))) {
    return false;
  }

  return true;
});

const items = $input.all();

return items.map((item, index) => ({
  json: {
    ...item.json,
    fetchIndex: index,
  },
}));

